import unittest
from decimal import Decimal

from tally.money import format_amount, parse_amount


class FormatAmountTest(unittest.TestCase):
    def test_formats_two_decimals(self):
        self.assertEqual(format_amount(Decimal("4.5")), "$4.50")

    def test_thousands_separator(self):
        self.assertEqual(format_amount(Decimal("1234.56")), "$1,234.56")

    def test_refund_is_negative(self):
        self.assertEqual(format_amount(Decimal("-12")), "-$12.00")


class ParseAmountTest(unittest.TestCase):
    def test_plain_amount(self):
        self.assertEqual(parse_amount("4.50"), Decimal("4.50"))

    def test_leading_dollar_sign(self):
        self.assertEqual(parse_amount("$4.50"), Decimal("4.50"))

    def test_thousands_separator(self):
        self.assertEqual(parse_amount("1,234.56"), Decimal("1234.56"))

    def test_surrounding_whitespace(self):
        self.assertEqual(parse_amount("  4.50  "), Decimal("4.50"))

    def test_negative_refund(self):
        self.assertEqual(parse_amount("-12.00"), Decimal("-12.00"))
        self.assertEqual(parse_amount("-$3"), Decimal("-3"))

    def test_invalid_input_raises_value_error(self):
        with self.assertRaises(ValueError):
            parse_amount("abc")
        with self.assertRaises(ValueError):
            parse_amount("")
        with self.assertRaises(ValueError):
            parse_amount("$" )
        with self.assertRaises(ValueError):
            parse_amount("1.2.3")


if __name__ == "__main__":
    unittest.main()
